  "sql": "WITH _base AS (\n  SELECT\n    items.order_id AS \"items.order_id\",\n    COUNT(*) AS \"items.count_all\"\n  FROM items AS items\n  LEFT JOIN orders AS orders\n    ON items.order_id = orders.id\n  WHERE\n    orders.ordered_at >= CAST('2025-01-01 00:00:00' AS TIMESTAMP)\n    AND orders.ordered_at < CAST('2026-01-01 00:00:00' AS TIMESTAMP)\n  GROUP BY\n    items.order_id\n), _cm_items__products__iif_type_jaffle_1_0_sum AS (\n  SELECT\n    SUM(CASE WHEN products.type = 'jaffle' THEN 1 ELSE 0 END) AS \"products.iif_type_jaffle_1_0_sum\"\n  FROM products AS products\n  WHERE\n    EXISTS(\n      SELECT\n        1\n      FROM items AS items\n      INNER JOIN orders AS items__orders\n        ON items.order_id = items__orders.id\n      WHERE\n        (\n          products.sku = items.sku\n          AND items__orders.ordered_at >= CAST('2025-01-01 00:00:00' AS TIMESTAMP)\n        )\n        AND items__orders.ordered_at < CAST('2026-01-01 00:00:00' AS TIMESTAMP)\n    )\n), _cm_items__products__iif_type_beverage_1_0_sum AS (\n  SELECT\n    SUM(CASE WHEN products.type = 'beverage' THEN 1 ELSE 0 END) AS \"products.iif_type_beverage_1_0_sum\"\n  FROM products AS products\n  WHERE\n    EXISTS(\n      SELECT\n        1\n      FROM items AS items\n      INNER JOIN orders AS items__orders\n        ON items.order_id = items__orders.id\n      WHERE\n        (\n          products.sku = items.sku\n          AND items__orders.ordered_at >= CAST('2025-01-01 00:00:00' AS TIMESTAMP)\n        )\n        AND items__orders.ordered_at < CAST('2026-01-01 00:00:00' AS TIMESTAMP)\n    )\n)\nSELECT\n  _base.\"items.order_id\",\n  _cm_items__products__iif_type_jaffle_1_0_sum.\"products.iif_type_jaffle_1_0_sum\" AS \"items.jaffles\",\n  _cm_items__products__iif_type_beverage_1_0_sum.\"products.iif_type_beverage_1_0_sum\" AS \"items.bevs\",\n  _base.\"items.count_all\"\nFROM _base\nCROSS JOIN _cm_items__products__iif_type_jaffle_1_0_sum\nCROSS JOIN _cm_items__products__iif_type_beverage_1_0_sum\nORDER BY\n  _base.\"items.order_id\" ASC\nLIMIT 11"
